import ast

class CodeCoverageGenerator(ast.NodeTransformer):
    def __init__(self):
        self.coverage = {}

    def visit_FunctionDef(self, node):
        func_name = node.name
        if func_name not in self.coverage:
            self.coverage[func_name] = 0
        # Mark function as executable
        self.generic_visit(node)
        return node

    def visit_If(self, node):
        # Increment the coverage count for each branch
        if 'if' not in self.coverage[node]:
            self.coverage[node]['if'] = 0
        if 'else' not in self.coverage[node]:
            self.coverage[node]['else'] = 0
        node.test.body.append(
            ast.Expr(ast.Call(
                ast.Name(id='track_coverage', ctx=ast.Load()),
                args=[ast.Str(s='if')],
                keywords=[]
            ))
        )
        node.test.orelse.append(
            ast.Expr(ast.Call(
                ast.Name(id='track_coverage', ctx=ast.Load()),
                args=[ast.Str(s='else')],
                keywords=[]
            ))
        )
        # Continue visiting
        self.generic_visit(node)
        return node

    def get_coverage(self):
        return self.coverage

def track_coverage(branch):
