    with tarfile.open(os.path.join(backup_dir, target_filename), 'w') as tar:
        for file in files_to_backup:
            tar.add(file, arcname=os.path.relpath(file, start=source_dir))

def differential_backup(backup_root, source_dir):
    current_time = datetime.now().strftime('%Y%m%d%H%M%S')
    target_filename = f'backup_{current_time}.tar.gz'

    if not os.path.exists(backup_root):
        os.makedirs(backup_root)

    all_files = set(find_files_to_backup(source_dir))
    last_backup_file = os.path.join(backup_root, f'last_backup.{os.getpid()}')

    if os.path.isfile(last_backup_file):
        with open(last_backup_file, 'r') as f:
            last_backup_files = {line.strip() for line in f}
            new_files = all_files - last_backup_files
    else:
        new_files = all_files

    if new_files:
        create_tarball(backup_root, target_filename, new_files)
        with open(last_backup_file, 'w') as f:
            for file in all_files:
                f.write(f'{file}\n')

if __name__ == '__main__':
    source_dir = '/path/to/source/directory'
    backup_root = '/path/to/backup/root'
    differential_backup(backup_root, source_dir)
```

