class PackageInstaller:
    def __init__(self, repository_url: str):
        self.repository_url = repository_url

    def install_deb(self, package_name: str) -> None:
        command = f"wget {self.repository_url}/{package_name}.deb -O /tmp/{package_name}.deb && dpkg -i /tmp/{package_name}.deb"
