    def install_rpm(self, package_name: str) -> None:
        command = f"wget {self.repository_url}/{package_name}.rpm -O /tmp/{package_name}.rpm && rpm -ivh /tmp/{package_name}.rpm"
        subprocess.run(command, shell=True, check=True)

