import os
import hashlib
import shutil

def get_file_hash(file_path):
    """Calculate the SHA-256 hash of a file."""
    hasher = hashlib.sha256()
    with open(file_path, 'rb') as f:
        buf = f.read(65536)
        while buf:
            hasher.update(buf)
            buf = f.read(65536)
    return hasher.hexdigest()

def find_duplicate_files(directory):
    """Find all duplicate files in a given directory."""
    file_hashes = {}
    duplicates = {}

    for root, _, files in os.walk(directory):
        for file_name in files:
            file_path = os.path.join(root, file_name)
            file_hash = get_file_hash(file_path)
            if file_hash in file_hashes:
                duplicates.setdefault(file_hash, []).append(file_path)
            else:
                file_hashes[file_hash] = [file_path]

    # Remove files without duplicates
    duplicates = {hash_val: paths for hash_val, paths in duplicates.items() if len(paths) > 1}
    return duplicates

def delete_redundant_files(duplicates, backup_dir=None):
    """Delete all but one copy of each duplicate file."""
    for file_hash, paths in duplicates.items():
        keep_path = paths.pop()
        for path_to_delete in paths:
            try:
                print(f"Deleting {path_to_delete}")
                if backup_dir:
                    shutil.copy(path_to_delete, backup_dir)
                os.remove(path_to_delete)
            except Exception as e:
                print(f"Error deleting {path_to_delete}: {e}")

def set_permissions(files, permission_mode):
    """Set permissions on specified files."""
    for file_path in files:
        try:
            print(f"Setting permissions for {file_path} to {permission_mode}")
            os.chmod(file_path, permission_mode)
        except Exception as e:
            print(f"Error setting permissions for {file_path}: {e}")

# Example usage
