    """Find duplicate files in a given directory."""
    hashes = {}
    duplicates = []

    for root, _, files in os.walk(directory):
        for file in files:
            file_path = os.path.join(root, file)
            if os.path.islink(file_path):
                continue  # Skip symlinks
            file_hash = calculate_hash(file_path)
            if file_hash in hashes:
                duplicates.append((hashes[file_hash], file_path))
            else:
                hashes[file_hash] = file_path

    return duplicates

def remove_redundant_files(duplicates):
    """Remove all but one instance of each duplicate pair."""
    seen = set()
    to_delete = set()

    for original, duplicate in duplicates:
        if original not in seen:
            seen.add(original)
        else:
            to_delete.add(duplicate)

    for path in to_delete:
        try:
            os.remove(path)
            print(f"Deleted redundant file: {path}")
        except Exception as e:
            print(f"Failed to delete {path}: {e}")

def change_permissions(files, mode):
