class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end_of_word = False

class AutocompleteTool:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_end_of_word = True

    def search_prefix(self, prefix):
        node = self.root
        for char in prefix:
            if char not in node.children:
                return []
            node = node.children[char]
        return self._collect_words(node, prefix)

    def _collect_words(self, node, current_prefix):
        words = []
        if node.is_end_of_word:
            words.append(current_prefix)
        for char, child_node in node.children.items():
            words.extend(self._collect_words(child_node, current_prefix + char))
        return words

# Example usage
autocomplete_tool = AutocompleteTool()
words = ["apple", "application", "app", "banana", "bear"]
for word in words:
    autocomplete_tool.insert(word)

# Test autocomplete with prefix 'app'
