import os
import hashlib
from pathlib import Path
from concurrent.futures import ThreadPoolExecutor

def calculate_hash(file_path):
    hasher = hashlib.md5()
    with open(file_path, 'rb') as f:
        while chunk := f.read(8192):
            hasher.update(chunk)
    return file_path, hasher.hexdigest()

def compare_hashes(local_hashes, remote_hashes):
    add_files = []
    remove_files = []

    for path, local_hash in local_hashes.items():
        if path not in remote_hashes:
            add_files.append(path)

    for path, remote_hash in remote_hashes.items():
        if path not in local_hashes:
            remove_files.append(path)
        elif local_hashes[path] != remote_hash:
            add_files.append(path)
            remove_files.append(path)

    return add_files, remove_files

def synchronize_files(local_path, remote_path, max_workers=4):
    local_hashes = {}
    remote_hashes = {}

    def worker(path):
        return calculate_hash(path)

    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        for result in executor.map(worker, Path(local_path).rglob('*')):
            local_hashes[result[0]] = result[1]

    try:
        # Simulate fetching remote hashes
        for path, _ in local_hashes.items():
            remote_hashes[path] = 'simulated_hash'
    except Exception as e:
        print(f"Error fetching remote hashes: {e}")
        return

    add_files, remove_files = compare_hashes(local_hashes, remote_hashes)

    for file in add_files:
        source_file = Path(file).relative_to(Path(local_path))
        target_file = Path(remote_path) / source_file
        target_file.parent.mkdir(parents=True, exist_ok=True)
        os.symlink(source_file, target_file)
        print(f"Symlinked {file} -> {target_file}")

    for file in remove_files:
        if Path(file).is_symlink():
            Path(file).unlink()
            print(f"Removed symlink {file}")

