import os
import hashlib
from rsync import Rsync

def compute_hash(file_path):
    hasher = hashlib.md5()
    with open(file_path, 'rb') as f:
        buf = f.read(4096)
        while len(buf) > 0:
            hasher.update(buf)
            buf = f.read(4096)
    return hasher.hexdigest()

def sync_files(source_dir, destination_dirs):
    for root, _, files in os.walk(source_dir):
        for file in files:
            source_file_path = os.path.join(root, file)
            dest_file_hashes = {dest: None for dest in destination_dirs}

            for dest in destination_dirs:
                dest_file_path = os.path.join(dest, file[2:])
                if os.path.exists(dest_file_path):
                    dest_file_hashes[dest] = compute_hash(dest_file_path)

            if any(hash_val != dest_file_hashes[dest] for dest, hash_val in dest_file_hashes.items()):
                rsync = Rsync()
                rsync.add_source(source_file_path)
                rsync.add_destination(os.path.dirname(dest_file_path))
                rsync.execute()

