        except paramiko.AuthenticationException:
            logger.error(f"Authentication failed for {self.host}")
            raise

    def disconnect(self):
        try:
            self.client.close()
            logger.info(f"Disconnected from {self.host}")
        except Exception as e:
            logger.error(f"Failed to disconnect from {self.host}: {str(e)}")
            raise

    def get_files(self) -> Dict[str, str]:
        try:
            self.connect()
            stdin, stdout, stderr = self.client.exec_command('ls -l')
            files = {line.split()[8] for line in stdout.readlines()}
            self.disconnect()
            return dict(files)
        except Exception as e:
            logger.error(f"Failed to get files from {self.host}: {str(e)}")
            raise

    def get_local_files(self, directory: str = '.') -> Dict[str, str]:
        try:
            return {file: str(os.path.getmtime(os.path.join(directory, file)))
                    for file in os.listdir(directory) if os.path.isfile(os.path.join(directory, file))}
        except Exception as e:
            logger.error(f"Failed to get local files: {str(e)}")
            raise

    def synchronize(self, local_dir: str, remote_dir: str):
        logger.info("Synchronizing files...")
        local_files = self.get_local_files(local_dir)
        remote_files = self.get_files()
        logger.info("Connecting to remote host...")
        self.connect()
        stdin, stdout, stderr = self.client.exec_command(f"cd {remote_dir} && ls -l")
        for file_remote in [line.split()[8] for line in stdout.readlines()]:
            if file_remote not in local_files.keys():
                local_file = local_files.get(file_remote)
                if local_file:
                    logger.info(f"Uploading {file_remote}...")
                    stdin, stdout, stderr = self.client.exec_command(
                        f"scp {os.path.join(local_dir, file_remote)} {remote_dir}")
                    logger.info(f"{file_remote} uploaded successfully")
                else:
                    logger.info(f"Removing {file_remote} from remote host...")
                    stdin, stdout, stderr = self.client.exec_command(f"rm {remote_dir}/{file_remote}")
                    logger.info(f"{file_remote} removed from remote host successfully")
            elif local_files[file_remote] < int(stdout.channel.recv(12)):
                logger.info(f"Updating {file_remote}...")
                stdin, stdout, stderr = self.client.exec_command(f"cp {remote_dir}/{file_remote} {os.path.join(local_dir, file_remote)}")
                logger.info(f"{file_remote} updated successfully")
        for file_local in local_files.keys():
            if file_local not in remote_files:
                logger.info(f"Uploading {file_local}...")
                stdin, stdout, stderr = self.client.exec_command(
                    f"scp {os.path.join(local_dir, file_local)} {remote_dir}")
                logger.info(f"{file_local} uploaded successfully")
        self.disconnect()

    def run(self, local_dir: str, remote_dir: str):
        try:
            if not os.path.exists(local_dir):
                logger.error(f"Local directory {local_dir} does not exist")
                return
            self.synchronize(local_dir, remote_dir)
        except Exception as e:
            logger.error(str(e))

if __name__ == "__main__":
    host = 'localhost'
    username = 'user'
    password = 'password'
    port = 22
    local_dir = '/path/to/local/directory'
    remote_dir = '/path/to/remote/directory'

    synchronizer = Synchronizer(host, username, password, port)
    synchronizer.run(local_dir, remote_dir)
```

