import os
import shutil
import getpass
import paramiko
import datetime

class FileSynchronizer:
    def __init__(self, host, username, password, destination_path):
        self.host = host
        self.username = username
        self.password = password
        self.destination_path = destination_path

    def connect(self):
        try:
            self.transport = paramiko.Transport((self.host, 22))
            self.transport.connect(username=self.username, password=self.password)
            self.sftp = paramiko.SFTPClient.from_transport(self.transport)
            return self.sftp
        except paramiko.AuthenticationException:
            print("Authentication failed")
            return None

    def download_file(self, file_path):
        try:
            self.sftp.get(file_path, filename=None)
            self.sftp.remove(file_path)
            return True
        except FileNotFoundError:
            print(f"File {file_path} not found on server")
            return False
        except Exception as e:
            print(f"Error downloading file {file_path}: {e}")
            return False

    def upload_file(self, file_path):
        try:
            self.sftp.put(file_path, file_path)
            return True
        except FileNotFoundError:
            print(f"File {file_path} not found")
            return False
        except Exception as e:
            print(f"Error uploading file {file_path}: {e}")
            return False

    def close_sftp(self):
        self.sftp.close()
        self.transport.close()

    def synchronize(self, source_path):
        for root, dirs, files in os.walk(source_path):
            for dir in dirs:
                dest_path = os.path.join(self.destination_path, os.path.relpath(root, source_path))
                self.sftp.mkdir(dest_path)
            for file in files:
                file_path = os.path.join(root, file)
                if file_path!= source_path:
                    relative_path = os.path.relpath(file_path, source_path)
                    dest_path = os.path.join(self.destination_path, relative_path)
                    if file_path.startswith(source_path) and os.path.getmtime(file_path) > os.path.getmtime(dest_path):
                        if os.path.isfile(dest_path):
                            self.sftp.remove(dest_path)
                        self.upload_file(file_path)
                        print(f"Uploading file {file_path}")
                    else:
                        if os.path.isfile(file_path):
                            self.download_file(relative_path)
                            print(f"Downloading file {file_path}")
                    for dir in dirs:
                        dest_dir = os.path.join(self.destination_path, os.path.relpath(root, source_path), dir)
                        target_dir = os.path.join(root, dir)
                        for file in os.listdir(target_dir):
                            source_file = os.path.join(target_dir, file)
                            if source_file.startswith(target_dir) and not os.path.isfile(os.path.join(dest_dir, file)):
                                self.sftp.mkdir(os.path.join(dest_dir, file))
                                print(f"Creating directory {os.path.join(dest_dir, file)}")

def main():
    host = input("Enter the server host: ")
    username = input("Enter the username: ")
    password = getpass.getpass("Enter the password: ")
    source_path = input("Enter the source path: ")
    destination_path = "/remote/destination/path"
    synchronizer = FileSynchronizer(host, username, password, destination_path)
    sftp = synchronizer.connect()
    synchronizer.synchronize(source_path)
    synchronizer.close_sftp()

if __name__ == "__main__":
    main()
