class DeployPipeline:
    def __init__(self, repo_url, branch, deploy_dir, token):
        self.repo_url = repo_url
        self.branch = branch
        self.deploy_dir = deploy_dir
        self.token = token

    def checkout_code(self):
        try:
            repo = Repo.clone_from(self.repo_url, self.deploy_dir)
            repo.git.checkout(self.branch)
            return True
        except:
            return False

    def get_commit_hash(self):
        try:
            repo = Repo(self.deploy_dir)
            return repo.head.commit.hexsha
        except:
            return None

    def get_file_hash(self, filename):
        try:
            with open(filename, 'rb') as file:
                return hashlib.md5(file.read()).hexdigest()
        except:
            return None

    def deploy(self):
        if not self.checkout_code():
            print("Failed to checkout code")
            sys.exit(1)
        commit_hash = self.get_commit_hash()
        if not commit_hash:
            print("Failed to get commit hash")
            sys.exit(1)
        file_hash = self.get_file_hash('main.py')
        if not file_hash:
            print("Failed to get file hash")
            sys.exit(1)
        try:
            subprocess.run(['git', 'add', '.'], cwd=self.deploy_dir)
            subprocess.run(['git', 'commit', '-m', 'deploy: {} ({})'.format(commit_hash, file_hash)], cwd=self.deploy_dir)
            subprocess.run(['git', 'push', '-u', 'origin', self.branch], cwd=self.deploy_dir)
            return True
        except:
            return False

if __name__ == '__main__':
