class DeploymentSystem:
    def __init__(self, source_archive, server_details):
        self.source_archive = source_archive
        self.server_details = server_details

    def extract_archive(self):
        if self.source_archive.endswith('.tar.gz') or self.source_archive.endswith('.tar'):
            with tarfile.open(self.source_archive, 'r:gz' if self.source_archive.endswith('.tar.gz') else 'r') as tar:
                tar.extractall()
        elif self.source_archive.endswith('.zip'):
            with zipfile.ZipFile(self.source_archive, 'r') as zip_ref:
                zip_ref.extractall()

    def copy_dependencies(self):
        src_path = os.path.join(os.getcwd(), 'extracted_source')
        for dependency in self.server_details['dependencies']:
            file_name = dependency['filename']
            path = os.path.join(src_path, file_name)
            shutil.copy(path, '/usr/local/lib')

    def install_and_config(self):
        script_path = os.path.join(os.getcwd(), 'extracted_source','script.sh')
        if os.path.exists(script_path):
            subprocess.run(['bash', script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)

    def deploy_to_server(self):
        processes = []
        for dep in multiprocessing.cpu_count():
            process = multiprocessing.Process(target=self.copy_dependencies)
            processes.append(process)
            process.start()
        for process in processes:
            process.join()

    def run_deployment(self):
        if not os.path.exists('extracted_source'):
            self.extract_archive()
        self.deploy_to_server()

if __name__ == "__main__":
