            self.mysql_conn.close()
            logging.info("Disconnected from MySQL database")

    def dump_mysql_db(self, backup_file):
        if not self.mysql_conn:
            self.connect_to_mysql()

        cursor = self.mysql_conn.cursor()
        cursor.execute("SELECT @@GLOBAL.GTID_EXECUTED")
        result = cursor.fetchone()
        cursor.close()

        try:
            with open(backup_file, 'w') as f:
                sql_file = f"""
                    SET FOREIGN_KEY_CHECKS=0;
                    SET GLOBAL SQL_SAFE_UPDATES = 0;
                    DELIMITER //
                    SHOW MASTER STATUS;
                    SHOW MASTER LOGS;
                    FLUSH TABLES WITH READ LOCK;
                    SET GLOBAL GTID_EXECUTED = '{result[0]}';
                    SHOW GLOBAL VARIABLES LIKE 'MAX_ALLOWED_PACKET';
                    SHOW GLOBAL VARIABLES LIKE 'bulk_insert_max_size';
                    SHOW TABLE STATUS;
                    SHOW MASTER STATUS;
                    SHOW GLOBAL VARIABLES LIKE '%max_binlog_cache_size%';
                    SHOW GLOBAL VARIABLES LIKE '%max_connections%';
                    SHOW GLOBAL VARIABLES LIKE 'query_cache_type';
                    SHOW ENGINE InnoDB STATUS;
                    RESET MASTER;
                    UNLOCK TABLES;
                    SET GLOBAL FOREIGN_KEY_CHECKS=1;
                    SET GLOBAL UNIQUE_CHECKS=1;
                    DELIMITER ;
                    """

                f.write(sql_file)
                cursor = self.mysql_conn.cursor(dictionary=True)
                query = f"mysqldump -h {self.db_host} -u {self.db_user} -p'{self.db_password}' -d {self.db_name}"
                result = os.popen(query).read()
                cursor.close()

                with open(backup_file, 'a') as f:
                    f.write(result)
            logging.info("MySQL database dumped successfully")
        except Exception as e:
            logging.error(f"Failed to dump MySQL database: {e}")

    def dump_sqlite_db(self, db_file):
        if not self.sqlite3_conn:
            self.sqlite3_conn = sqlite3.connect(db_file)
            self.sqlite3_cursor = self.sqlite3_conn.cursor()
            logging.info("Connected to SQLite3 database")

        try:
            self.sqlite3_cursor.execute('SELECT name FROM sqlite_master ORDER BY name')
            rows = self.sqlite3_cursor.fetchall()
            with open(db_file, 'w') as db:
                for row in rows:
                    table_name = row[0]
                    self.sqlite3_cursor.execute(f"SELECT * FROM {table_name}")
                    rows = self.sqlite3_cursor.fetchall()
                    db.write(f"CREATE TABLE {table_name} (\n")
                    for i, column_name in enumerate([desc[0] for desc in self.sqlite3_cursor.description]):
                        db.write(f"    {column_name} TEXT\n")
                        if i!= max([x[1] for x in self.sqlite3_cursor.description]) - 1:
                            db.write(",\n")
                    db.write("\n);")
                    db.write("\n")
                    for row in rows:
                        row_str = '\t'.join(row) + '\n'
                        db.write(row_str)
            logging.info("SQLite database dumped successfully")
        except Exception as e:
            logging.error(f"Failed to dump SQLite database: {e}")

    def restore_db(self, backup_file):
        if self.mysql_conn:
            self.disconnect_from_mysql()

        # Restoring MySQL database
        query = f"mysql -h {self.db_host} -u {self.db_user} -p'{self.db_password}' {self.db_name} < {backup_file}"
        try:
            result = os.popen(query).read()
            if not result.startswith("Database restored successfully"):
                raise Exception("Database restore failed")
            logging.info("MySQL database restored successfully")
        except Exception as e:
            logging.error(f"Failed to restore MySQL database: {e}")

        # Restoring SQLite database
        self.sqlite3_conn = sqlite3.connect(backup_file)
        self.sqlite3_cursor = self.sqlite3_conn.cursor()
        try:
            self.sqlite3_cursor.executescript(open(backup_file, "r").read())
            self.sqlite3_conn.commit()
            self.sqlite3_conn.close()
            logging.info("SQLite database restored successfully")
        except Exception as e:
            logging.error(f"Failed to restore SQLite database: {e}")

def main():
