import os
import shutil
import stat
import time
import getpass
import paramiko
import logging
from pathlib import Path
from datetime import datetime
from itertools import product

# Set up logger
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

class FileSync:
    def __init__(self, local_path, remote_path, username, remote_ip, password):
        self.local_path = local_path
        self.remote_path = remote_path
        self.username = username
        self.remote_ip = remote_ip
        self.password = password

    def connect_to_remote(self):
        try:
            self.client = paramiko.SSHClient()
            self.client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
            self.client.connect(self.remote_ip, username=self.username, password=self.password)
            logger.info('Connected to remote host successfully')
        except Exception as e:
            logger.error('Failed to connect to remote host')
            return False
        return True

    def get_remote_files(self):
        try:
            stdin, stdout, stderr = self.client.exec_command('ls')
            files = stdout.readlines()
            return [f.strip() for f in files]
        except Exception as e:
            logger.error('Failed to get remote files')
            return []

    def sync_files(self):
        try:
            # Get local and remote files
            local_files = os.listdir(self.local_path)
            remote_files = self.get_remote_files()

            # Find files to sync
            files_to_sync = [f for f in local_files if os.path.isfile(os.path.join(self.local_path, f)) and f not in remote_files]

            # Download files from remote to local
            for remote_file in remote_files:
                if os.path.exists(os.path.join(self.local_path, remote_file)):
                    src = os.path.join(self.remote_path, remote_file)
                    dst = os.path.join(self.local_path, remote_file)
                    if self._file_is_stale(src, dst):
                        self.download_file(src, dst)
                else:
                    src = os.path.join(self.remote_path, remote_file)
                    self.download_file(src, os.path.join(self.local_path, remote_file))

            # Upload files from local to remote
            for file in files_to_sync:
                src = os.path.join(self.local_path, file)
                dst = os.path.join(self.remote_path, file)
                if not os.path.exists(dst):
                    self.upload_file(src, dst)

            # Clean up old files on remote
            for file in remote_files:
                remote_file_path = os.path.join(self.remote_path, file)
                if not os.path.exists(remote_file_path):
                    self.client.exec_command(f'rm {remote_file_path}')
        except Exception as e:
            logger.error('Failed to sync files')
            return False
        return True

    def _file_is_stale(self, src, dst):
        try:
            src_mtime = datetime.fromtimestamp(os.path.getmtime(src))
            dst_mtime = datetime.fromtimestamp(os.path.getmtime(dst))
            return src_mtime < dst_mtime
        except Exception as e:
            return False

    def download_file(self, src, dst):
        try:
            self.client.exec_command(f'cp {src} {dst}')
            logger.info(f'Downloaded {src} to {dst}')
        except Exception as e:
            logger.error(f'Failed to download {src} to {dst}')

    def upload_file(self, src, dst):
        try:
            self.client.send_file(src, dst)
            logger.info(f'Uploaded {src} to {dst}')
        except Exception as e:
            logger.error(f'Failed to upload {src} to {dst}')

def main():
    local_path = input('Enter the local path: ')
    remote_path = input('Enter the remote path: ')
    username = input('Enter the remote username: ')
    remote_ip = input('Enter the remote IP: ')
    password = getpass.getpass('Enter the remote password: ')

    sync = FileSync(local_path, remote_path, username, remote_ip, password)

    sync.connect_to_remote()

    if sync.sync_files():
        logger.info('Files synced successfully')
    else:
        logger.error('Failed to sync files')

if __name__ == '__main__':
    main()
