from enum import Enum

class Environment(Enum):
    """Enum for different environments"""
    STAGING = "staging"
    QA = "qa"
    PRODUCTION = "production"

class Role(Enum):
    """Enum for different user roles"""
    ADMIN = "admin"
    DEVELOPER = "developer"
    OPERATOR = "operator"

class User:
    """Class to hold user permissions"""
    def __init__(self, role, environment):
        self.role = role
        self.environment = environment

class Action:
    """Class to hold allowed actions for each role in an environment"""
    def __init__(self, admin_actions, developer_actions, operator_actions):
        self.admin_actions = admin_actions
        self.developer_actions = developer_actions
        self.operator_actions = operator_actions

class Permissions:
    """Class to check and grant access to users"""
    def __init__(self):
        self.role_actions = {
            Role.ADMIN: Action(["deploy", "update", "delete"],
                             [],
                             []),
            Role.DEVELOPER: Action([], ["update", "push"],
                                ["view"]),
            Role.OPERATOR: Action([], [], ["view", "restart"]),
        }
        self.environment_access = {
            Environment.STAGING: [Role.ADMIN, Role.DEVELOPER],
            Environment.QA: [Role.ADMIN, Role.DEVELOPER, Role.OPERATOR],
            Environment.PRODUCTION: [Role.ADMIN],
        }

    def has_access(self, user, action_name):
        """Check if a user has access to an action in a given environment"""
        if user.environment not in self.environment_access:
            return False

        if user.role in self.environment_access[user.environment]:
            if user.role == Role.ADMIN:
                return True
            elif user.role == Role.DEVELOPER and action_name in self.role_actions[user.role].developer_actions:
                return True
            elif user.role == Role.OPERATOR and action_name in self.role_actions[user.role].operator_actions:
                return True
        return False

permissions = Permissions()
deployer = User(Role.DEVELOPER, Environment.STAGING)
operator = User(Role.OPERATOR, Environment.QA)

