from ftplib import FTP
import paramiko
import select

class Server:
    def __init__(self, hostname, port, username, password, remote_path):
        self.hostname = hostname
        self.port = port
        self.username = username
        self.password = password
        self.remote_path = remote_path
        self.ssh = paramiko.SSHClient()
        self.ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())

    def connect_ssh(self):
        try:
            self.ssh.connect(self.hostname, port=self.port, username=self.username, password=self.password)
            return True
        except paramiko.AuthenticationException:
            print(f"Authentication failed for {self.hostname}")
            return False

    def transfer_file_via_ssh(self, local_path):
        try:
            ftp = self.ssh.open_sftp()
            ftp.put(local_path, os.path.join(self.remote_path, os.path.basename(local_path)))
            ftp.close()
            return True
        except Exception as e:
            print(f"Error transferring file via SSH to {self.hostname}: {e}")
            return False

class FTPServer:
    def __init__(self, hostname, port, username, password, remote_path):
        self.hostname = hostname
        self.port = port
        self.username = username
        self.password = password
        self.remote_path = remote_path
        self.ftp = FTP(self.hostname)

    def connect_ftp(self):
        try:
            self.ftp.login(self.username, self.password)
            return True
        except Exception as e:
            print(f"Error connecting to FTP server {self.hostname}: {e}")
            return False

    def transfer_file_via_ftp(self, local_path):
        try:
            self.ftp.storbinary(f"STOR {os.path.basename(local_path)}", open(local_path, 'rb'))
            return True
        except Exception as e:
            print(f"Error transferring file via FTP to {self.hostname}: {e}")
            return False

class ArchiveManager:
    def __init__(self, source_path, archive_name):
        self.source_path = source_path
        self.archive_name = archive_name
        self.tar = tarfile.TarFile(self.archive_name, 'w')

    def create_archive(self):
        self.tar.add(self.source_path, arcname='')
        self.tar.close()

class ServerUploader:
    def __init__(self, servers, local_path):
        self.servers = servers
        self.local_path = local_path

    def transfer(self):
        for server in self.servers:
            if isinstance(server, Server) and server.connect_ssh():
                self.transfer_via_ssh(server)
            elif isinstance(server, FTPServer) and server.connect_ftp():
                self.transfer_via_ftp(server)

    def transfer_via_ssh(self, server):
        server.transfer_file_via_ssh(self.local_path)

    def transfer_via_ftp(self, server):
        server.transfer_file_via_ftp(self.local_path)

class ArchiveUploader:
    def __init__(self, servers, source_path, archive_name):
        self.servers = servers
        self.source_path = source_path
        self.archive_name = archive_name
        self.archive_manager = ArchiveManager(source_path, archive_name)
        self.server_uploader = ServerUploader(servers, self.archive_name)

    def create_archive(self):
        self.archive_manager.create_archive()

    def upload(self):
        self.create_archive()
        self.server_uploader.transfer()

