class SFTPTransfer:
    def __init__(self, host, username, password, remote_dir, local_dir):
        self.host = host
        self.username = username
        self.password = password
        self.remote_dir = remote_dir
        self.local_dir = local_dir
        self.sftp = None

    def connect(self):
        try:
            self.sftp = paramiko.SFTPClient()
            self.sftp.connect(hostname=self.host, username=self.username, password=self.password)
        except paramiko.AuthenticationException as e:
            logging.error(f"Authentication failed: {e}")
            self.sftp = None

    def disconnect(self):
        self.sftp.close()
        self.sftp = None

    def upload(self):
        if not self.sftp:
            self.connect()

        if not self.sftp:
            return False

        try:
            for root, dirs, files in os.walk(self.local_dir):
                for file in files:
                    local_file_path = os.path.join(root, file)
                    remote_file_path = os.path.join(self.remote_dir, os.path.relpath(local_file_path, self.local_dir))

                    logging.info(f"Uploading file: {local_file_path}")
                    self.sftp.put(local_file_path, remote_file_path)

            logging.info("Upload successful")
            return True
        except Exception as e:
            logging.error(f"Upload failed: {e}")
            return False

    def compare(self):
        if not self.sftp:
            self.connect()

        if not self.sftp:
            return False

        def get_files(remote_dir):
            files = []
            for _, dirs, _ in self.sftp.listdir_recurse(remote_dir):
                files.extend(dirs)
                files.extend(f for f in self.sftp.listdir(remote_dir) if not self.is_dir(f))
            return files

        local_files = set(os.listdir(self.local_dir))
        remote_files = set(get_files(self.remote_dir))

        return local_files == remote_files

    def is_dir(self, filename):
        try:
            _ = self.sftp.stat(os.path.join(self.remote_dir, filename))
            return self.sftp.lstat(os.path.join(self.remote_dir, filename)).st_mode & 0o40700  # Check if file is a dir
        except:
            return False

    def match_file_contents(self, filename):
        local_file_path = os.path.join(self.local_dir, filename)
        try:
            with open(local_file_path, 'rb') as f:
                local_hash = hashlib.md5(f.read()).hexdigest()
        except FileNotFoundError:
            return False

        remote_file_path = os.path.join(self.remote_dir, filename)
        try:
            with self.sftp.open(remote_file_path, 'rb') as f:
                remote_hash = hashlib.md5(f.read()).hexdigest()
        except FileNotFoundError:
            return False

        return local_hash == remote_hash


