            if entry.date == self._get_current_date():
                entry.backups.append(job)
                return
        entry = ReportEntry(self._get_current_date(), [job])
        self.entries.append(entry)

    def get_summary(self) -> str:
        report = ""
        for entry in self.entries:
            report += f"Date: {entry.date}\n"
            for job in entry.backups:
                report += f"  {job.filename} ({job.status})\n"
        return report

