def sync(remote, local):
    transport = paramiko.Transport((remote.split('/')[2], 22))
    transport.connect(username=os.environ.get('REMOTE_USERNAME'), password=os.environ.get('REMOTE_PASSWORD'))
    sftp = paramiko.SFTPClient.from_transport(transport)

    os.makedirs(local, exist_ok=True)

    try:
        sftp.chdir(remote)
    except IOError:
        print(f'Permission denied for path: {remote}')
        return

    for item in sftp.listdir():
        remote_path = os.path.join(remote, item)
        local_path = os.path.join(local, item)
        try:
            if sftp.stat(remote_path).st_mode & stat.S_IRUSR:
                sftp.get(remote_path, local_path)
            elif sftp.stat(remote_path).st_mode & stat.S_IWUSR:
                with open(local_path, 'wb') as f, sftp.open(remote_path, 'rb') as r:
                    f.write(r.read())
        except FileNotFoundError:
            print(f'File not found on remote server: {remote_path}')
        except PermissionError:
            print(f'Permission denied for file: {remote_path}')
        if os.path.isdir(local_path):
            sync(sftp, remote_path, local_path)
        else:
            continue

    transport.close()

